BEGIN;
SET LOCAL standard_conforming_strings = on;
-- Fonte: dados/originais/ana_barragens_hidreletricas.csv (UTF-8).
-- 887 registros, 33 campos e 29.271 células originais; vazios preservados como ''.
-- Capacidade mantida como texto; valor padronizado NULL por ausência de unidade comprovada.
-- Equipe: Alexandre Arthur, Enrique Luis e Renan Gomes.
SELECT setval('municipio_id_municipio_seq', (SELECT COALESCE(MAX(id_municipio), 1) FROM municipio), true);
SELECT setval('empreendedor_id_empreendedor_seq', (SELECT COALESCE(MAX(id_empreendedor), 1) FROM empreendedor), true);
SELECT setval('regiao_hidrografica_id_regiao_hidrografica_seq', (SELECT COALESCE(MAX(id_regiao_hidrografica), 1) FROM regiao_hidrografica), true);
SELECT setval('comite_federal_id_comite_federal_seq', (SELECT COALESCE(MAX(id_comite_federal), 1) FROM comite_federal), true);
SELECT setval('comite_estadual_id_comite_estadual_seq', (SELECT COALESCE(MAX(id_comite_estadual), 1) FROM comite_estadual), true);
SELECT setval('unidade_gestao_id_unidade_gestao_seq', (SELECT COALESCE(MAX(id_unidade_gestao), 1) FROM unidade_gestao), true);
SELECT setval('registro_origem_id_registro_seq', (SELECT COALESCE(MAX(id_registro), 1) FROM registro_origem), true);
COMMIT;
